pub fn run<'a>(
    config: &'a aws_config::SdkConfig,
    operation: &'a str,
    input: &'a Value,
    options: &'a Options,
) -> core::CommandFuture<'a> {
    Box::pin(async move {
        let mut config = aws_sdk_connecthealth::config::Builder::from(config);
        if let Some(endpoint) = &options.endpoint_url {
            config = config.endpoint_url(endpoint);
        }
        let client = aws_sdk_connecthealth::Client::from_conf(config.build());
        let output = Output::new(options.clone());
        let command: core::CommandFuture<'_> = match operation {
            "activate_subscription" => {
                Box::pin(call_activate_subscription(&client, input, &output))
            }
            "create_domain" => Box::pin(call_create_domain(&client, input, &output)),
            "create_subscription" => Box::pin(call_create_subscription(&client, input, &output)),
            "deactivate_subscription" => {
                Box::pin(call_deactivate_subscription(&client, input, &output))
            }
            "delete_domain" => Box::pin(call_delete_domain(&client, input, &output)),
            "get_domain" => Box::pin(call_get_domain(&client, input, &output)),
            "get_medical_scribe_listening_session" => Box::pin(
                call_get_medical_scribe_listening_session(&client, input, &output),
            ),
            "get_patient_insights_job" => {
                Box::pin(call_get_patient_insights_job(&client, input, &output))
            }
            "get_subscription" => Box::pin(call_get_subscription(&client, input, &output)),
            "list_domains" => Box::pin(call_list_domains(&client, input, &output)),
            "list_subscriptions" => Box::pin(call_list_subscriptions(&client, input, &output)),
            "list_tags_for_resource" => {
                Box::pin(call_list_tags_for_resource(&client, input, &output))
            }
            "start_medical_scribe_listening_session" => Box::pin(
                call_start_medical_scribe_listening_session(&client, input, &output),
            ),
            "start_patient_insights_job" => {
                Box::pin(call_start_patient_insights_job(&client, input, &output))
            }
            "tag_resource" => Box::pin(call_tag_resource(&client, input, &output)),
            "untag_resource" => Box::pin(call_untag_resource(&client, input, &output)),
            _ => return Err(CliError::input(format!("unknown operation: {operation}"))),
        };
        command
            .await
            .map_err(|error| error.context("connecthealth", operation))
    })
}
